-- Migration: make OpenRouter the canonical Star Vault embedding route.
--
-- OpenAI-compatible direct access and Gemini remain supported as explicit
-- fallbacks, but the default provider/model must match Tweet Vault so vectors
-- generated by the scheduled Edge Function and the Bun CLI share one space.

set
  search_path = public,
  extensions;

alter table star_vault.repos
  alter column embedding_provider set default 'openrouter',
  alter column embedding_model set default 'openai/text-embedding-3-small';

alter table star_vault.repos
  drop constraint if exists repos_embedding_provider_check;

alter table star_vault.repos
  add constraint repos_embedding_provider_check
  check (embedding_provider in ('openrouter', 'openai', 'gemini'));

-- Recreate the search RPC defaults. The provider/model filters remain explicit
-- so old vectors are never searched with OpenRouter query vectors by accident.
create or replace function star_vault.search_repos (
  query_embedding vector (1536),
  match_threshold float default 0.7,
  match_count int default 10,
  embedding_provider_filter text default 'openrouter',
  embedding_model_filter text default 'openai/text-embedding-3-small',
  embedding_dim_filter int default 1536
) returns table (
  id bigint,
  full_name text,
  description text,
  topics text[],
  language text,
  html_url text,
  stargazers_count integer,
  forks_count integer,
  starred_at timestamptz,
  content_fetched_at timestamptz,
  content_checked_at timestamptz,
  content_changed_at timestamptz,
  source_changed_at timestamptz,
  embedding_provider text,
  embedding_model text,
  embedding_dim int,
  embedding_generated_at timestamptz,
  similarity float
) language plpgsql stable as $$
begin
  perform set_config('hnsw.ef_search', '100', true);

  return query
    select
      r.id,
      r.full_name,
      r.description,
      r.topics,
      r.language,
      r.html_url,
      r.stargazers_count,
      r.forks_count,
      r.starred_at,
      r.content_fetched_at,
      r.content_checked_at,
      r.content_changed_at,
      r.source_changed_at,
      r.embedding_provider,
      r.embedding_model,
      r.embedding_dim,
      r.embedding_generated_at,
      (-(r.embedding <#> query_embedding))::float as similarity
    from star_vault.repos r
    where r.embedding is not null
      and r.embedding_provider = embedding_provider_filter
      and r.embedding_model = embedding_model_filter
      and r.embedding_dim = embedding_dim_filter
      and (-(r.embedding <#> query_embedding)) > match_threshold
    order by r.embedding <#> query_embedding
    limit match_count;
end;
$$;

grant execute on function star_vault.search_repos (vector (1536), float, int, text, text, int) to service_role;
